<?php /** 赛事业务视图；负责人：王乐之（2411302）；AI辅助开发。 */ use yii\helpers\{Html,Url};$this->title='动态图表';$this->registerJsFile('@web/js/worldcup-charts.js',['depends'=>[yii\web\YiiAsset::class]]);?><h1>赛事动态图表</h1><form id="wc-chart-filter" class="wc-filters" data-url="<?= Html::encode(Url::to(['statistics/data'])) ?>"><select name="tournament_id"><?php foreach($tournaments as $t):?><option value="<?= $t->id ?>"><?= Html::encode($t->name) ?></option><?php endforeach ?></select><select name="stage_id"><option value="">全部阶段</option><?php foreach($stages as $s):?><option value="<?= $s->id ?>"><?= Html::encode($s->name) ?></option><?php endforeach ?></select><select name="team_id"><option value="">全部球队</option><?php foreach($teams as $t):?><option value="<?= $t->id ?>"><?= Html::encode($t->name) ?></option><?php endforeach ?></select><button>刷新图表</button></form><p id="wc-chart-status" role="status"></p><div class="wc-chart-grid"><section class="card"><h2>球队进球对比</h2><div id="wc-teams"></div></section><section class="card"><h2>比赛进球趋势</h2><div id="wc-trend"></div></section><section class="card"><h2>阶段进球分布</h2><div id="wc-stages"></div></section><section class="card"><h2>球员个人数据对比</h2><div id="wc-players"></div></section></div>